import { jitter, sleep } from "./time"

const CAP_MS = 60_000
const GIVE_UP_MS = 10 * 60_000

export async function keepOpen(socket) {
  let tries = 0
  for (;;) {
    await socket.open()
    tries += 1
    await sleep(Math.min(CAP_MS, 1000 * 2 ** tries) + jitter(250))
  }
}

